            },
            "problemMatcher": []
        },
        {
            "label": "task6",
            "type": "shell",
            "command": "echo Task6 && sleep 5",
            "presentation": {
                "terminalGroup": "group"
            },
            "problemMatcher": []
        },
    ]
}
```
</details>

